package com.wordlock.test;
import android.app.*; import android.content.*; import android.os.*; import android.graphics.*; import android.view.*; import android.widget.*;
public class WordService extends Service {
String[][] words={{"Embrace","Kucaklamak"},{"Achieve","Başarmak"},{"Improve","Geliştirmek"},{"Discover","Keşfetmek"},{"Courage","Cesaret"},{"Believe","İnanmak"},{"Journey","Yolculuk"},{"Hope","Umut"},{"Effort","Çaba"},{"Dream","Hayal"},{"Learn","Öğrenmek"},{"Peace","Huzur"},{"Kindness","Nezaket"},{"Focus","Odaklanmak"},{"Create","Yaratmak"},{"Trust","Güvenmek"},{"Wonder","Merak etmek"},{"Patience","Sabır"},{"Freedom","Özgürlük"},{"Opportunity","Fırsat"}};
int i=-1; WindowManager wm; LinearLayout overlay;
BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent in){if(Intent.ACTION_SCREEN_ON.equals(in.getAction())){if(getSystemService(KeyguardManager.class).isKeyguardLocked())show();}else hide();}};
public void onCreate(){super.onCreate(); wm=getSystemService(WindowManager.class); NotificationManager nm=getSystemService(NotificationManager.class); nm.createNotificationChannel(new NotificationChannel("wordlock","WordLock",2)); startForeground(1,new Notification.Builder(this,"wordlock").setSmallIcon(android.R.drawable.ic_menu_info_details).setContentTitle("WordLock testi etkin").setVisibility(Notification.VISIBILITY_SECRET).build()); IntentFilter f=new IntentFilter(); f.addAction(Intent.ACTION_SCREEN_ON); f.addAction(Intent.ACTION_SCREEN_OFF); f.addAction(Intent.ACTION_USER_PRESENT); registerReceiver(receiver,f,Context.RECEIVER_NOT_EXPORTED);}
int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
void show(){hide(); i=(i+1)%words.length; overlay=new LinearLayout(this); overlay.setOrientation(1); for(int j=0;j<2;j++){TextView t=new TextView(this); t.setText(words[i][j]); t.setTextSize(j==0?21:13); t.setTextColor(Color.WHITE); t.setTypeface(j==0?Typeface.SERIF:Typeface.DEFAULT); t.setShadowLayer(4,0,1,Color.BLACK); overlay.addView(t);} WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT); p.gravity=Gravity.BOTTOM|Gravity.LEFT; p.x=dp(20);p.y=dp(118);try{wm.addView(overlay,p);}catch(RuntimeException e){overlay=null;}}
void hide(){if(overlay!=null){try{wm.removeView(overlay);}catch(RuntimeException e){}overlay=null;}}
public void onDestroy(){hide();unregisterReceiver(receiver);super.onDestroy();}public IBinder onBind(Intent i){return null;}
}